CREATE OR REPLACE FUNCTION get_ewrii(equip_code text)
RETURNS numeric AS $$
DECLARE
    v_power_source text;
    v_conversion_eff numeric;
    v_water_level real;
    v_water_quality bigint;
    v_waste_tank real;
    v_heater_temp real;
    v_esi numeric;
    v_wrmi numeric;
    v_ewrii numeric;
    v_multiplier numeric;
BEGIN
    -- Get power source and conversion efficiency from PowerBattery
    SELECT "battery_telemetry"->'power_state'->>'primary_source',
           ("battery_telemetry"->'power_state'->>'conversion_eff_pct')::numeric
    INTO v_power_source, v_conversion_eff
    FROM "PowerBattery"
    WHERE "equip_ref" = equip_code;

    -- If no battery data, try ThermalSolarWindAndGrid for solar/wind info
    IF v_power_source IS NULL THEN
        SELECT DISTINCT "powerQualIdx", NULL
        INTO v_power_source, v_conversion_eff
        FROM "ThermalSolarWindAndGrid" t
        JOIN "Communication" c ON t."comm_link" = c."COMM_ID"
        WHERE c."equipRef" = equip_code
        LIMIT 1;
    END IF;

    -- Calculate ESI multiplier based on power source
    CASE
        WHEN v_power_source IN ('Solar', 'Wind', 'Hybrid') THEN v_multiplier := 1.5;
        WHEN v_power_source = 'Battery' THEN v_multiplier := 1.0;
        WHEN v_power_source = 'Diesel' THEN v_multiplier := 0.7;
        ELSE v_multiplier := 0;
    END CASE;

    -- ESI = energy_efficiency_percent * multiplier
    v_esi := COALESCE(v_conversion_eff, 0) * v_multiplier;

    -- Get water data from WaterAndWaste
    SELECT "waterLevelPct", "waterQualityIdx", "wasteTankPct"
    INTO v_water_level, v_water_quality, v_waste_tank
    FROM "WaterAndWaste"
    WHERE "equipRef" = equip_code;

    -- WRMI = (water_level_pct/100) * (water_quality_idx/100) * (1 - waste_tank_pct/100)
    v_wrmi := COALESCE(v_water_level, 0) / 100.0 
             * COALESCE(v_water_quality, 0) / 100.0 
             * (1.0 - COALESCE(v_waste_tank, 0) / 100.0);

    -- Get heater temperature from CabinEnvironment
    SELECT ("cabin_env_snapshot"->'hvac'->>'heater_temp_c')::real
    INTO v_heater_temp
    FROM "CabinEnvironment"
    WHERE "equipRef" = equip_code;

    -- EWRII = 0.5 * ESI + 0.5 * WRMI * (1 - heater_temp/100)
    v_ewrii := 0.5 * v_esi + 0.5 * v_wrmi * (1.0 - COALESCE(v_heater_temp, 0) / 100.0);

    RETURN ROUND(CAST(v_ewrii AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_ewrii(equip_code text)
RETURNS numeric AS $$
DECLARE
    v_power_source text;
    v_conversion_eff numeric;
    v_water_level real;
    v_water_quality bigint;
    v_waste_tank real;
    v_heater_temp real;
    v_esi numeric;
    v_wrmi numeric;
    v_ewrii numeric;
    v_multiplier numeric;
BEGIN
    -- Get power source and conversion efficiency from PowerBattery
    SELECT "battery_telemetry"->'power_state'->>'primary_source',
           ("battery_telemetry"->'power_state'->>'conversion_eff_pct')::numeric
    INTO v_power_source, v_conversion_eff
    FROM "PowerBattery"
    WHERE "equip_ref" = equip_code;

    -- If no battery data found, try to get from ThermalSolarWindAndGrid via Communication
    IF v_power_source IS NULL THEN
        SELECT DISTINCT t."solarEffPct", NULL
        INTO v_power_source, v_conversion_eff
        FROM "ThermalSolarWindAndGrid" t
        JOIN "Communication" c ON t."comm_link" = c."COMM_ID"
        WHERE c."equipRef" = equip_code
        LIMIT 1;
        -- Set a default power source if still null
        IF v_power_source IS NULL THEN
            v_power_source := 'Unknown';
        END IF;
    END IF;

    -- Calculate ESI multiplier based on power source
    CASE
        WHEN v_power_source IN ('Solar', 'Wind', 'Hybrid') THEN v_multiplier := 1.5;
        WHEN v_power_source = 'Battery' THEN v_multiplier := 1.0;
        WHEN v_power_source = 'Diesel' THEN v_multiplier := 0.7;
        ELSE v_multiplier := 0;
    END CASE;

    -- ESI = energy_efficiency_percent * multiplier
    v_esi := COALESCE(v_conversion_eff, 0) * v_multiplier;

    -- Get water data from WaterAndWaste
    SELECT "waterLevelPct", "waterQualityIdx", "wasteTankPct"
    INTO v_water_level, v_water_quality, v_waste_tank
    FROM "WaterAndWaste"
    WHERE "equipRef" = equip_code;

    -- WRMI = (water_level_pct/100) * (water_quality_idx/100) * (1 - waste_tank_pct/100)
    v_wrmi := COALESCE(v_water_level, 0) / 100.0 
             * COALESCE(v_water_quality, 0) / 100.0 
             * (1.0 - COALESCE(v_waste_tank, 0) / 100.0);

    -- Get heater temperature from CabinEnvironment
    SELECT ("cabin_env_snapshot"->'hvac'->>'heater_temp_c')::real
    INTO v_heater_temp
    FROM "CabinEnvironment"
    WHERE "equipRef" = equip_code;

    -- EWRII = 0.5 * ESI + 0.5 * WRMI * (1 - heater_temp/100)
    v_ewrii := 0.5 * v_esi + 0.5 * v_wrmi * (1.0 - COALESCE(v_heater_temp, 0) / 100.0);

    RETURN ROUND(CAST(v_ewrii AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

SELECT e."EquipType", e."EQUIP_CODE", get_ewrii(e."EQUIP_CODE") as ewrii_score 
FROM "Equipment" e 
ORDER BY e."EquipType", ewrii_score DESC;
